-- and bury the handful this project actually defines.
CREATE OR REPLACE FUNCTION public.check_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
  v_count integer;
begin
  insert into rate_limits as r (key, count, window_start)
  values (p_key, 1, now())
  on conflict (key) do update
    set count = case
          when r.window_start < now() - make_interval(secs => p_window_seconds)
            then 1
          else r.count + 1
        end,
        window_start = case
          when r.window_start < now() - make_interval(secs => p_window_seconds)
            then now()
          else r.window_start
        end
  returning r.count into v_count;

  -- Keys for callers that never return would otherwise accumulate forever.
  -- Cleaning up on roughly 1 in 1000 calls keeps the table bounded without
  -- needing a scheduled job.
  if random() < 0.001 then
    delete from rate_limits where window_start < now() - interval '1 day';
  end if;

  return v_count <= p_limit;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.consume_usage(p_uid text, p_fp text, p_field text, p_limit integer)
 RETURNS TABLE(allowed boolean, used integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_used integer := 0; v_new integer; v_updated integer := 0; v_rows integer;
  k_uid bigint; k_fp bigint;
begin
  if p_field not in ('eval_count','chat_count','topper_clicks') then
    raise exception 'unsupported field %', p_field;
  end if;
  if coalesce(p_uid,'') = '' and coalesce(p_fp,'') = '' then
    return query select false, 0; return;
  end if;
  k_uid := hashtext('usage:uid:' || coalesce(p_uid,''));
  k_fp := hashtext('usage:fp:' || coalesce(p_fp,''));
  if coalesce(p_uid,'') <> '' and coalesce(p_fp,'') <> '' then
    perform pg_advisory_xact_lock(least(k_uid,k_fp));
    perform pg_advisory_xact_lock(greatest(k_uid,k_fp));
  elsif coalesce(p_uid,'') <> '' then
    perform pg_advisory_xact_lock(k_uid);
  else
    perform pg_advisory_xact_lock(k_fp);
  end if;
  execute format('select coalesce(max(%I),0) from usage_tracking where (nullif($1,'''') is not null and firebase_uid = $1) or (nullif($2,'''') is not null and fingerprint = $2)', p_field)
    into v_used using coalesce(p_uid,''), coalesce(p_fp,'');
  if v_used >= p_limit then
    return query select false, v_used; return;
  end if;
  v_new := v_used + 1;
  if coalesce(p_uid,'') <> '' then
    execute format('update usage_tracking set %I = $2, updated_at = now() where firebase_uid = $1', p_field) using p_uid, v_new;
    get diagnostics v_rows = row_count; v_updated := v_updated + v_rows;
  end if;
  if coalesce(p_fp,'') <> '' then
    execute format('update usage_tracking set %I = $2, updated_at = now() where fingerprint = $1', p_field) using p_fp, v_new;
    get diagnostics v_rows = row_count; v_updated := v_updated + v_rows;
  end if;
  if v_updated = 0 then
    execute format('insert into usage_tracking (fingerprint, firebase_uid, %I) values (coalesce(nullif($1,''''), ''uid_'' || $2), nullif($2,''''), $3) on conflict do nothing', p_field)
      using coalesce(p_fp,''), coalesce(p_uid,''), v_new;
  end if;
  return query select true, v_new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_zero_duration_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.session_duration_secs = 0 THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$function$
