-- Policies. A table with RLS on and no policy denies every non-service role.
create policy "own annotations" on annotations as PERMISSIVE for ALL to public using ((auth.uid() = user_id));
create policy "Users manage own canvas annotations" on canvas_annotations as PERMISSIVE for ALL to public using ((auth.uid() = user_id));
create policy "Users manage own chat usage" on chat_usage as PERMISSIVE for ALL to public using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "Allow insert only" on contact_submissions as PERMISSIVE for INSERT to public with check (true);
create policy "Admin all debates" on debates as PERMISSIVE for ALL to public using (true) with check (true);
create policy "Public read debates" on debates as PERMISSIVE for SELECT to public using (true);
create policy "Service role full access" on device_sessions as PERMISSIVE for ALL to service_role using (true) with check (true);
create policy "Users manage own usage" on eval_usage as PERMISSIVE for ALL to public using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "read overrides" on note_overrides as PERMISSIVE for SELECT to public using (true);
create policy "Public can read notifications" on notifications as PERMISSIVE for SELECT to anon, authenticated using (true);
create policy "Admin all positions" on positions as PERMISSIVE for ALL to public using (true) with check (true);
create policy "Public read positions" on positions as PERMISSIVE for SELECT to public using (true);
create policy "read published posts" on posts as PERMISSIVE for SELECT to public using ((published = true));
create policy "Auth delete" on pyq_answers as PERMISSIVE for DELETE to public using ((auth.uid() = user_id));
create policy "Auth insert" on pyq_answers as PERMISSIVE for INSERT to public with check ((auth.uid() = user_id));
create policy "Public read" on pyq_answers as PERMISSIVE for SELECT to public using (true);
create policy "anyone can insert" on pyq_comments as PERMISSIVE for INSERT to public with check (true);
create policy "anyone can read" on pyq_comments as PERMISSIVE for SELECT to public using (true);
create policy "anyone can upvote" on pyq_comments as PERMISSIVE for UPDATE to public using (true);
create policy "Allow read only" on subscription_slots as PERMISSIVE for SELECT to public using (true);
create policy "Users read own subscription" on subscriptions as PERMISSIVE for SELECT to public using ((auth.uid() = user_id));
create policy "Public can read topper_copies" on topper_copies as PERMISSIVE for SELECT to public using (true);
create policy "Public can read topper_copy_pyq_map" on topper_copy_pyq_map as PERMISSIVE for SELECT to public using (true);
create policy "service role only" on topper_subscriptions as PERMISSIVE for ALL to public using (false);
create policy "Allow all for service role" on usage_tracking as PERMISSIVE for ALL to public using (true) with check (true);
create policy "Users manage own profile" on user_profiles as PERMISSIVE for ALL to public using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "Allow all for service role" on user_sessions as PERMISSIVE for ALL to public using (true) with check (true);
create policy allow_visitor_tracking on user_sessions as PERMISSIVE for ALL to public using (true) with check (true);
create policy service_only on user_sessions as PERMISSIVE for ALL to public using (false) with check (false);
create policy "Users can delete own pads" on writing_pads as PERMISSIVE for DELETE to public using ((auth.uid() = user_id));
create policy "Users can insert own pads" on writing_pads as PERMISSIVE for INSERT to public with check ((auth.uid() = user_id));
create policy "Users can update own pads" on writing_pads as PERMISSIVE for UPDATE to public using ((auth.uid() = user_id));
create policy "Users can view own pads" on writing_pads as PERMISSIVE for SELECT to public using ((auth.uid() = user_id));

